<div class="welcome-row"><div><div class="form-kicker">PATRIMÔNIO PESSOAL</div><h1>Patrimônio e dívidas</h1><p class="page-subtitle">Acompanhe ativos, obrigações e o patrimônio líquido mês a mês.</p></div></div><?php if($errors): ?><div class="alert error"><?=e(implode(' ',$errors))?></div><?php endif; ?>
<div class="metric-grid"><article class="metric-card"><div class="metric-label">Total de ativos <span class="metric-symbol green">↗</span></div><div class="metric-value"><?=money($assetTotal)?></div><div class="metric-foot">Contas + investimentos + bens</div></article><article class="metric-card"><div class="metric-label">Dívidas restantes <span class="metric-symbol coral">↘</span></div><div class="metric-value"><?=money($liabilityTotal)?></div><div class="metric-foot">Saldo de obrigações em aberto</div></article><article class="metric-card"><div class="metric-label">Patrimônio líquido <span class="metric-symbol blue">◎</span></div><div class="metric-value"><?=money($netWorth)?></div><div class="metric-foot">Ativos menos passivos</div></article></div>
<div class="charts-grid"><section class="panel dashboard-chart"><div class="panel-head"><div><h3>Evolução patrimonial</h3><p>Fechamento mensal registrado ao consultar esta página</p></div></div><?php if($history): ?><div class="canvas-box"><canvas id="balance-chart" aria-label="Evolução mensal do patrimônio líquido"></canvas></div><?php else: ?><div class="chart-empty">Ainda não há fechamentos mensais.</div><?php endif; ?></section><section class="panel dashboard-chart"><div class="panel-head"><div><h3>Composição dos ativos</h3><p>Saldos atuais por grupo</p></div></div><div class="patrimony-breakdown"><div><span>Contas/caixa (exceto contas de investimento)</span><b><?=money($accountTotal)?></b></div><div><span>Investimentos</span><b><?=money($investments)?></b></div><div><span>Bens cadastrados</span><b><?=money(array_sum(array_map(fn($row)=>(int)$row['current_value'],array_filter($assets,fn($row)=>(int)$row['is_active']===1))))?></b></div></div><a class="text-link" href="/investments">Gerenciar investimentos →</a></section></div>
<div class="patrimony-columns"><section class="panel statement-panel"><div class="panel-head"><div><h3>Bens cadastrados</h3><p>Imóveis, veículos, dinheiro e outros ativos manuais.</p></div></div><?php if($assets): ?><div class="table-wrap"><table><thead><tr><th>Bem</th><th>Tipo</th><th>Atualizado</th><th class="right">Valor</th><th></th></tr></thead><tbody><?php foreach($assets as $asset): ?><tr><td><?=e($asset['name'])?><?=$asset['is_active']?'':' · Arquivado'?></td><td><?=e($assetsTypes[$asset['type']]??$asset['type'])?></td><td><?=e(date('d/m/Y',strtotime($asset['valuation_date'])))?></td><td class="right"><?=money((int)$asset['current_value'])?></td><td class="row-actions"><a href="/patrimony?edit_asset=<?=(int)$asset['id']?>#asset-form">Editar</a><form method="post" action="/patrimony/asset/toggle"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$asset['id']?>"><button class="row-cancel"><?=$asset['is_active']?'Arquivar':'Reativar'?></button></form></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state">Nenhum bem manual cadastrado.</div><?php endif; ?></section>
<section class="panel statement-panel"><div class="panel-head"><div><h3>Dívidas e obrigações</h3><p>Pagamentos registram uma despesa e reduzem o passivo na mesma transação.</p></div></div><?php if($liabilities): ?><div class="table-wrap"><table><thead><tr><th>Obrigação</th><th>Vencimento</th><th class="right">Saldo</th><th>Baixa</th></tr></thead><tbody><?php foreach($liabilities as $debt): ?><tr><td><?=e($debt['name'])?><?=$debt['is_active']?'':' · Arquivada'?> <a href="/patrimony?edit_liability=<?=(int)$debt['id']?>#liability-form">Editar</a><small class="debt-type"><?=e($liabilityTypes[$debt['type']]??$debt['type'])?></small></td><td><?=$debt['due_date']?e(date('d/m/Y',strtotime($debt['due_date']))):'—'?></td><td class="right amount-out"><?=money((int)$debt['remaining_amount'])?></td><td><?php if($debt['is_active']): ?><form method="post" action="/patrimony/liability/pay" class="debt-pay-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$debt['id']?>"><input name="amount" inputmode="decimal" placeholder="Valor" required><select name="account_id" required><option value="">Conta</option><?php foreach($accountsForPayment as $account): ?><option value="<?=(int)$account['id']?>"><?=e($account['name'])?></option><?php endforeach; ?></select><select name="category_id"><option value="">Categoria</option><?php foreach($expenseCategories as $category): ?><option value="<?=(int)$category['id']?>"><?=e($category['name'])?></option><?php endforeach; ?></select><input type="hidden" name="payment_date" value="<?=date('Y-m-d')?>"><button>Baixar</button></form><?php endif; ?><form method="post" action="/patrimony/liability/toggle"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$debt['id']?>"><button class="row-cancel"><?=$debt['is_active']?'Arquivar':'Reativar'?></button></form></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state">Nenhuma dívida cadastrada.</div><?php endif; ?></section></div>
<div class="patrimony-forms"><section class="panel editor-panel" id="asset-form"><div class="panel-head"><div><h3><?=$editAsset?'Editar bem ou ativo':'Cadastrar bem ou ativo'?></h3><p>Informe a última avaliação conhecida.</p></div></div><form method="post" action="/patrimony/asset/save" class="data-form single"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)($editAsset['id']??0)?>"><label>Nome<input name="name" maxlength="100" required placeholder="Ex.: Automóvel" value="<?=e($editAsset['name']??'')?>"></label><label>Tipo<select name="type"><?php foreach($assetsTypes as $key=>$label): ?><option value="<?=e($key)?>" <?=($editAsset['type']??'')===$key?'selected':''?>><?=e($label)?></option><?php endforeach; ?></select></label><label>Valor atual<input name="current_value" inputmode="decimal" required placeholder="0,00" value="<?=isset($editAsset['current_value'])?e(money_input((int)$editAsset['current_value'])):''?>"></label><label>Data da avaliação<input name="valuation_date" type="date" value="<?=e($editAsset['valuation_date']??date('Y-m-d'))?>" required></label><label>Observações<input name="notes" maxlength="500" value="<?=e($editAsset['notes']??'')?>"></label><button class="button primary">Salvar bem</button><?php if($editAsset): ?><a class="button secondary" href="/patrimony">Cancelar</a><?php endif; ?></form></section>
<section class="panel editor-panel" id="liability-form"><div class="panel-head"><div><h3><?=$editLiability?'Editar dívida':'Cadastrar dívida'?></h3><p>O valor restante compõe o total de passivos.</p></div></div><form method="post" action="/patrimony/liability/save" class="data-form single"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)($editLiability['id']??0)?>"><label>Nome<input name="name" maxlength="100" required placeholder="Ex.: Financiamento do veículo" value="<?=e($editLiability['name']??'')?>"></label><label>Tipo<select name="type"><?php foreach($liabilityTypes as $key=>$label): ?><option value="<?=e($key)?>" <?=($editLiability['type']??'')===$key?'selected':''?>><?=e($label)?></option><?php endforeach; ?></select></label><label>Valor original<input name="original_amount" inputmode="decimal" required placeholder="0,00" value="<?=isset($editLiability['original_amount'])?e(money_input((int)$editLiability['original_amount'])):''?>"></label><label>Saldo restante<input name="remaining_amount" inputmode="decimal" required placeholder="0,00" value="<?=isset($editLiability['remaining_amount'])?e(money_input((int)$editLiability['remaining_amount'])):''?>"></label><label>Próximo vencimento<input name="due_date" type="date" value="<?=e($editLiability['due_date']??'')?>"></label><label>Observações<input name="notes" maxlength="500" value="<?=e($editLiability['notes']??'')?>"></label><button class="button primary">Salvar dívida</button><?php if($editLiability): ?><a class="button secondary" href="/patrimony">Cancelar</a><?php endif; ?></form></section></div>
